   834	asn1_read_value_type (asn1_node root, const char *name, void *ivalue,
   835	                      int *len, unsigned int *etype)
   836	{
   837	  asn1_node node, p, p2;
   838	  int len2, len3, result;
   839	  int value_size = *len;
   840	  unsigned char *value = ivalue;
   841	  unsigned type;
   842	
   843	  node = asn1_find_node (root, name);
   844	  if (node == NULL)
   845	    return ASN1_ELEMENT_NOT_FOUND;
   846	
   847	  type = type_field (node->type);
   848	
   849	  if ((type != ASN1_ETYPE_NULL) &&
   850	      (type != ASN1_ETYPE_CHOICE) &&
   851	      !(node->type & CONST_DEFAULT) && !(node->type & CONST_ASSIGN) &&
   852	      (node->value == NULL))
   853	    return ASN1_VALUE_NOT_FOUND;
   854	
   855	  if (etype)
   856	    *etype = type;
   857	  switch (type)
   858	    {
   859	    case ASN1_ETYPE_NULL:
   860	      PUT_STR_VALUE (value, value_size, "NULL");
   861	      break;
   862	    case ASN1_ETYPE_BOOLEAN:
   863	      if ((node->type & CONST_DEFAULT) && (node->value == NULL))
   864	        {
   865	          p = node->down;
   866	          while (type_field (p->type) != ASN1_ETYPE_DEFAULT)
   867	            p = p->right;
   868	          if (p->type & CONST_TRUE)
   869	            {
   870	              PUT_STR_VALUE (value, value_size, "TRUE");
   871	            }
   872	          else
   873	            {
   874	              PUT_STR_VALUE (value, value_size, "FALSE");
   875	            }
   876	        }
   877	      else if (node->value[0] == 'T')
   878	        {
   879	          PUT_STR_VALUE (value, value_size, "TRUE");
   880	        }
   881	      else
   882	        {
   883	          PUT_STR_VALUE (value, value_size, "FALSE");
   884	        }
   885	      break;
   886	    case ASN1_ETYPE_INTEGER:
   887	    case ASN1_ETYPE_ENUMERATED:
   888	      if ((node->type & CONST_DEFAULT) && (node->value == NULL))
   889	        {
   890	          p = node->down;
   891	          while (type_field (p->type) != ASN1_ETYPE_DEFAULT)
   892	            p = p->right;
   893	          if ((isdigit (p->value[0])) || (p->value[0] == '-')
   894	              || (p->value[0] == '+'))
   895	            {
   896	              result = _asn1_convert_integer
   897	                  (p->value, value, value_size, len);
   898	              if (result != ASN1_SUCCESS)
   899	                return result;
   900	            }
   901	          else
   902	            {                   /* is an identifier like v1 */
   903	              p2 = node->down;
   904	              while (p2)
   905	                {
   906	                  if (type_field (p2->type) == ASN1_ETYPE_CONSTANT)
   907	                    {
   908	                      if (!_asn1_strcmp (p2->name, p->value))
   909	                        {
   910	                          result = _asn1_convert_integer
   911	                              (p2->value, value, value_size,
   912	                               len);
   913	                          if (result != ASN1_SUCCESS)
   914	                            return result;
   915	                          break;
   916	                        }
   917	                    }
   918	                  p2 = p2->right;
   919	                }
   920	            }
   921	        }
   922	      else
   923	        {
   924	          len2 = -1;
   925	          result = asn1_get_octet_der
   926	              (node->value, node->value_len, &len2, value, value_size,
   927	               len);
   928	          if (result != ASN1_SUCCESS)
   929	            return result;
   930	        }
   931	      break;
   932	    case ASN1_ETYPE_OBJECT_ID:
   933	      if (node->type & CONST_ASSIGN)
   934	        {
   935	          *len = 0;
   936	          if (value)
   937	            value[0] = 0;
   938	          p = node->down;
   939	          while (p)
   940	            {
   941	              if (type_field (p->type) == ASN1_ETYPE_CONSTANT)
   942	                {
   943	                  ADD_STR_VALUE (value, value_size, p->value);
   944	                  if (p->right)
   945	                    {
   946	                      ADD_STR_VALUE (value, value_size, ".");
   947	                    }
   948	                }
   949	              p = p->right;
   950	            }
